const main = document.querySelector('main');
const nav = document.querySelector('nav');
const menu = document.querySelector('.menu-button');
const links = [...document.querySelectorAll('nav a')];
const pages = {
  home: () => `<section class="hero"><div class="container"><span class="eyebrow">PhilHealth redesign prototype</span><h1>Health information that is easier to find and use.</h1><p>A static, accessible prototype that keeps the homepage’s clear visual language across every public-facing page.</p><a class="button" href="#/about">Explore About Us</a></div></section><section class="section"><div class="container"><h2>Find what you need</h2><div class="grid">${card('Benefits','Clear guides to packages and eligibility.','Benefits')}${card('Member services','Start common tasks from one understandable place.','Online Services')}${card('Contact and help','Use clear support choices and escalation paths.','Contact Us')}</div></div></section>`,
  about: () => `<section class="page-intro"><div class="container"><span class="eyebrow">About PhilHealth</span><h1>One clear place to understand PhilHealth.</h1><p>The original About Us content is reorganized into a readable, responsive experience while keeping important institutional information easy to reach.</p></div></section><section class="service-strip"><div class="container two-col"><div><h2>Our role in public health</h2><p>PhilHealth helps members understand and use national health insurance benefits. This prototype groups its mandate, leadership, reports, and references around the questions citizens commonly ask.</p><a class="button" href="#/benefits">Explore benefits</a></div><aside class="notice"><strong>Need help now?</strong><p>Contact details are presented as clear, accessible actions in the full production design. This prototype does not collect personal information.</p></aside></div></section><section class="section"><div class="container"><h2>Explore About Us</h2><div class="grid">${card('Profile and history','Learn the agency history, mandate, vision, mission, and core values.','Profile')}${card('Leadership and organization','Find the board, executive officers, and organizational structure.','Leadership')}${card('Reports and references','Access annual reports, laws, studies, statistics, and public documents.','Reports')}</div></div></section><section class="section"><div class="container two-col"><div><h2>Information designed for everyone</h2><ul><li>Logical headings and landmark regions for screen-reader navigation.</li><li>Visible keyboard focus and a skip link.</li><li>Large text, high contrast, and no information conveyed by color alone.</li><li>Cards replace long, undifferentiated lists of links.</li></ul></div><div class="card highlight"><h3>Accessible by default</h3><p>Content is written in plain language and arranged for phones, desktops, keyboard users, and visitors using assistive technology.</p><a href="#/accessibility">Read the accessibility notes</a></div></div></section>`,
  benefits: () => simple('Benefits','Benefit information is organized by member goal, with readable summaries and clearly labelled next steps.'),
  members: () => simple('Members','A simplified member-information page for common questions, contribution guidance, and account-service entry points.'),
  partners: () => simple('Partners','Information for health-care providers and institutional partners, presented with consistent navigation.'),
  services: () => simple('Online Services','Service links would open clearly labelled destinations. This prototype contains no login, collection, or transaction flow.'),
  downloads: () => simple('Downloads','Forms and publications would include format, language, file size, and accessible HTML alternatives where available.'),
  contact: () => simple('Contact Us','A contact directory would provide clear channels, operating hours, and accessible help options.'),
  privacy: () => simple('Privacy notice','This is an academic prototype. It stores no information and does not represent an official government service.'),
  accessibility: () => simple('Accessibility notes','The prototype uses semantic regions, keyboard-accessible controls, focus indicators, readable type, responsive layouts, contrast-conscious colors, and descriptive navigation labels.'),
};
function card(title, body, link) { return `<article class="card"><h3>${title}</h3><p>${body}</p><a href="#/about">${link}</a></article>`; }
function simple(title, text) { return `<section class="page-intro"><div class="container"><span class="eyebrow">Prototype page</span><h1>${title}</h1><p>${text}</p><a class="button" href="#/about">Return to About Us</a></div></section>`; }
function render() { const route = location.hash.replace('#/','') || 'home'; main.innerHTML = (pages[route] || pages.home)(); document.title = `${route === 'home' ? 'Home' : route[0].toUpperCase()+route.slice(1)} | PhilHealth Redesign Prototype`; links.forEach(a => a.toggleAttribute('aria-current', a.getAttribute('href') === `#/${route}`)); nav.classList.remove('open'); menu.setAttribute('aria-expanded','false'); main.focus(); }
menu.addEventListener('click', () => { const state = menu.getAttribute('aria-expanded') === 'true'; menu.setAttribute('aria-expanded', String(!state)); nav.classList.toggle('open', !state); });
window.addEventListener('hashchange', render); render();
